import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s5-u13")
C = "B1"

L(1, "Even: suavizar pedidos", "Kun je even helpen? Wacht even!",
  ["Usar even para tornar pedidos mais leves"],
  vocab=[V("v-even-part","even (partícula)","(suaviza: só um momento, rapidinho)","adverb"), V("v-heel-even","heel even","só um bocadinho","expression"),
         V("v-even-niet","even niet","agora não (de momento)","expression"), V("v-eventjes","eventjes","um momentinho","adverb")],
  ex=[("Kun je even helpen?","Podes ajudar um bocadinho?"),("Wacht even!","Espera aí um momento!"),("Ik ga even boodschappen doen.","Vou só ali fazer umas compras."),("Nu even niet, ik ben druk.","Agora não, estou ocupado.")],
  gram=[G("g-even","Even","**even** (sem acento tónico) torna um pedido ou uma ação mais **pequena e leve**: *Kun je **even** de deur dichtdoen?* soa mais simpático do que sem *even*. Também indica algo rápido: *Ik ga even naar de winkel.* Não confundir com *even groot* (do mesmo tamanho).",
    [("Mag ik even je pen?","Emprestas-me a caneta um segundo?")],
    "É parecido com o nosso «só», «rapidinho» ou o diminutivo («um minutinho»).")],
  review=["v-even","v-wachten","v-helpen"],
  cefr=C, exs=[
    MA([("even","rapidinho"),("heel even","só um bocadinho"),("even niet","agora não"),("eventjes","um momentinho")], "Even.", ["v-even-part","v-heel-even","v-even-niet","v-eventjes"]),
    MC("Qual pedido soa mais simpático?", ["*Kun je even de deur dichtdoen?","Doe de deur dicht.|Imperativo seco.","Deur dicht!|Brusco."], "even suaviza.", ["v-even-part"]),
    TR("pt-nl","Espera aí um momento!", ["Wacht even","Wacht eventjes","Wacht even hoor"], "even.", ["v-even-part"]),
    TR("pt-nl","Vou só ali fazer umas compras.", ["Ik ga even boodschappen doen"], "even = rapidinho.", ["v-even-part"]),
    TR("nl-pt","Nu even niet, ik ben druk.", ["Agora não, estou ocupado","Agora não dá, estou ocupado"], "even niet.", ["v-even-niet"]),
    MC("Em «Ze zijn even groot», even significa…", ["*igualmente (do mesmo tamanho)","rapidinho|Aqui não é partícula.","agora não|Não."], "Dois sentidos.", ["v-even-part"]),
    WO("Emprestas-me a caneta um segundo?", ["Mag","ik","even","je","pen?"], "even depois do sujeito.", ["v-even-part"]),
    LI("Heb je heel even tijd?", ["Heb je heel even tijd","Heb jij heel even tijd"], "Tens só um bocadinho de tempo?", "heel even.", ["v-heel-even"]),
    FB("Ik bel je ___ terug.", ["even","zo"], "Rapidinho.", ["v-even-part"], choices=["even","heel","nooit"], tr="Ligo-te já de volta."),
    DL([("Collega","Heb je nu tijd voor een vraag?","Tens agora tempo para uma pergunta?"),("Tiago","")], ["*Nu even niet, over tien minuten wel.","Even.|Incompleto.","Nooit.|Brusco."], "Recusar temporariamente.", ["v-even-niet"]),
  ], diff=4, mins=6)

L(2, "Maar e eens: convites e imperativos simpáticos", "Kom maar binnen! Kijk eens!",
  ["Usar maar e eens para encorajar e convidar"],
  vocab=[V("v-maar-part","maar (partícula)","(encoraja: à vontade)","adverb",note="Kom maar binnen!"), V("v-eens-part","eens (partícula)","(convite: lá, então)","adverb",note="Kijk eens!"),
         V("v-ga-je-gang","ga je gang","faz favor|à vontade","expression"), V("v-zeg-het-maar","zeg het maar","diga (em que posso ajudar)","expression")],
  ex=[("Kom maar binnen!","Entra à vontade!"),("Kijk eens wat ik heb!","Olha lá o que eu tenho!"),("Ga je gang.","Faz favor."),("Zeg het maar.","Diga, faz favor.")],
  gram=[G("g-maar-eens","Maar e eens no imperativo","**maar** no imperativo = permissão/encorajamento: *Ga **maar** zitten* (sente-se à vontade). **eens** = convite ou curiosidade: *Probeer **eens*** (experimenta lá). Juntos: **maar eens** = «então vamos lá»: *Laten we maar eens beginnen.*",
    [("Neem maar een koekje.","Tira uma bolacha à vontade."),("Vertel eens!","Conta lá!")],
    "«maar» aqui não é «mas»!")],
  review=["v-maar","v-vertel-eens"],
  cefr=C, exs=[
    MA([("kom maar binnen","entra à vontade"),("kijk eens","olha lá"),("ga je gang","faz favor"),("zeg het maar","diga")], "Partículas.", ["v-maar-part","v-eens-part","v-ga-je-gang","v-zeg-het-maar"]),
    MC("Em «Ga maar zitten», maar significa…", ["*à vontade (encorajamento)","mas|Aqui não é conjunção.","só|Não."], "Partícula.", ["v-maar-part"]),
    TR("pt-nl","Entra à vontade!", ["Kom maar binnen","Kom gerust binnen"], "maar.", ["v-maar-part"]),
    TR("pt-nl","Conta lá!", ["Vertel eens","Vertel maar"], "eens.", ["v-eens-part"]),
    TR("nl-pt","Neem maar een koekje.", ["Tira uma bolacha à vontade","Serve-te de uma bolacha","Tira uma bolacha"], "maar.", ["v-maar-part"]),
    MC("O empregado diz «Zeg het maar». Ele quer…", ["*que faça o seu pedido","que se cale|Não.","que repita|Não necessariamente."], "Fórmula de serviço.", ["v-zeg-het-maar"]),
    WO("Experimenta lá!", ["Probeer","het","eens!"], "eens no fim.", ["v-eens-part"]),
    LI("Laten we maar eens beginnen.", ["Laten we maar eens beginnen"], "Então vamos lá começar.", "maar eens.", ["v-maar-part","v-eens-part"]),
    DL([("Ana","Mag ik je fiets even lenen?","Posso pedir-te a bicicleta emprestada um bocadinho?"),("Bram","")], ["*Ga je gang!","Maar.|Incompleto.","Eens.|Incompleto."], "Permitir.", ["v-ga-je-gang"]),
    FB("Kijk ___ hoe mooi de zonsondergang is!", ["eens"], "Convite.", ["v-eens-part"], choices=["eens","maar","even"], tr="Olha lá que bonito está o pôr do sol!"),
  ], diff=4, mins=6)

L(3, "Toch: contraste e insistência", "Je komt toch ook? Het is toch duidelijk?",
  ["Compreender os vários sentidos de toch"],
  vocab=[V("v-toch-part","toch (partícula)","(não é? / afinal / mesmo assim)","adverb"), V("v-toch-niet","toch niet","não, pois não?","expression"),
         V("v-dan-toch","dan toch","afinal sempre","expression"), V("v-jawel","jawel","sim (contrariando um «não»)","expression")],
  ex=[("Je komt toch ook?","Tu também vens, não vens?"),("Het regent, maar we gaan toch.","Está a chover, mas vamos na mesma."),("Hij is dan toch gekomen!","Afinal sempre veio!"),("Je bent toch niet boos? — Jawel!","Não estás zangado, pois não? — Estou, sim!")],
  gram=[G("g-toch","Toch","1) **Mesmo assim**: *Het is koud, maar ik ga toch.* 2) **Pergunta que espera confirmação**: *Je komt **toch**?* (vens, não vens?). 3) **Evidência/irritação**: *Dat weet je **toch**!* (tu sabes isso!). 4) **Afinal**: *Hij kwam **toch***. Responder «sim» a uma frase negativa: **jawel**.",
    [("Dat is toch logisch?","Isso é lógico, não é?")])],
  review=["v-toch","v-toch-conj"],
  cefr=C, exs=[
    MA([("toch?","não é?"),("toch niet?","pois não?"),("dan toch","afinal sempre"),("jawel","sim (contrariando)")], "Toch.", ["v-toch-part","v-toch-niet","v-dan-toch","v-jawel"]),
    MC("«Je komt toch ook?» — quem pergunta…", ["*espera que diga que sim","não sabe nada|Tem uma expectativa.","quer que não venha|Ao contrário."], "Confirmação.", ["v-toch-part"]),
    MC("«Je hebt geen honger?» — Tem fome. Responde…", ["*Jawel!","Ja!|Em resposta a uma pergunta negativa usa-se «jawel».","Nee!|Isso confirmaria que não tem fome."], "jawel.", ["v-jawel"]),
    TR("pt-nl","Está a chover, mas vamos na mesma.", ["Het regent(,) maar we gaan toch","Het regent(,) maar wij gaan toch"], "toch = mesmo assim.", ["v-toch-part"]),
    TR("nl-pt","Hij is dan toch gekomen!", ["Afinal sempre veio","Afinal ele sempre veio","Ele afinal veio"], "dan toch.", ["v-dan-toch"]),
    TR("pt-nl","Isso é lógico, não é?", ["Dat is toch logisch","Het is toch logisch"], "toch.", ["v-toch-part"]),
    MC("Em «Dat weet je toch!», o tom é…", ["*de evidência ou leve irritação («tu sabes isso!»)","de dúvida|Não.","de pergunta neutra|Não."], "Toch enfático.", ["v-toch-part"]),
    LI("Je bent toch niet ziek?", ["Je bent toch niet ziek","Jij bent toch niet ziek"], "Não estás doente, pois não?", "toch niet.", ["v-toch-niet"]),
    DL([("Moeder","Je hebt je huiswerk toch niet vergeten?","Não te esqueceste dos trabalhos de casa, pois não?"),("Zoon","")], ["*Nee hoor, het zit in mijn tas.","Jawel, het zit in mijn tas.|«Jawel» significaria que se esqueceu.","Toch.|Não responde."], "Responder à pergunta negativa.", ["v-toch-niet"]),
    FB("Ik was moe, maar ik ben ___ gaan sporten.", ["toch"], "Mesmo assim.", ["v-toch-part"], choices=["toch","even","eens"], tr="Estava cansado, mas fui na mesma fazer desporto."),
  ], diff=4, mins=7)

L(4, "Wel e nou: contraste e reação", "Ik heb geen auto, maar wel een fiets. Nou, nee!",
  ["Usar wel para contrastar e nou para reagir"],
  vocab=[V("v-wel-part","wel (partícula)","(contraste: sim, de facto)","adverb"), V("v-nou","nou","bem|então (reação)","expression"),
         V("v-nou-en","nou en?","e depois?","expression"), V("v-dat-wel","dat wel","isso sim","expression")],
  ex=[("Ik heb geen auto, maar wel een fiets.","Não tenho carro, mas tenho bicicleta."),("Het is wel duur.","É caro, lá isso é."),("Nou, dat valt mee!","Bem, não é assim tão mau!"),("Ik ben te laat. — Nou en?","Estou atrasado. — E depois?")],
  gram=[G("g-wel-nou","Wel e nou","**wel** é o contrário de **niet/geen**: *Ik rook niet, maar ik drink **wel**.* Também confirma com alguma reserva: *Het is **wel** mooi* (é bonito, sim…). **nou** abre uma reação: *Nou, nee!* (bem, não!), *Nou, gezellig!* (irónico ou sincero, depende do tom).",
    [("Ik kom morgen niet, maar overmorgen wel.","Amanhã não venho, mas depois de amanhã sim.")])],
  review=["v-niet","v-geen","v-maar-conj"],
  cefr=C, exs=[
    MA([("wel","sim (contraste)"),("nou","bem…"),("nou en?","e depois?"),("dat wel","isso sim")], "Wel e nou.", ["v-wel-part","v-nou","v-nou-en","v-dat-wel"]),
    TR("pt-nl","Não tenho carro, mas tenho bicicleta.", ["Ik heb geen auto(,) maar wel een fiets"], "geen … wel.", ["v-wel-part"]),
    TR("pt-nl","Amanhã não venho, mas depois de amanhã sim.", ["Morgen kom ik niet(,) maar overmorgen wel","Ik kom morgen niet(,) maar overmorgen wel"], "niet … wel.", ["v-wel-part"]),
    TR("nl-pt","Het is wel duur.", ["É caro, lá isso é","É caro, sim","Lá caro é"], "wel = concessão.", ["v-wel-part"]),
    FE(["Ik","rook","niet,","maar","ik","drink","niet","koffie."], 6, "wel", "Contraste com niet → wel.", ["v-wel-part"]),
    MC("«Nou en?» é uma reação…", ["*desafiadora/indiferente («e depois?»)","muito educada|Pode soar rude.","de agradecimento|Não."], "Cuidado com o tom.", ["v-nou-en"]),
    LI("Nou, dat valt best mee!", ["Nou(,) dat valt best mee"], "Bem, afinal não é assim tão mau!", "nou + meevallen.", ["v-nou","v-meevallen"]),
    DL([("Vriend","Dit restaurant is niet goedkoop.","Este restaurante não é barato."),("Rita","")], ["*Dat wel, maar het eten is heerlijk.","Nou en? Ik ben rijk.|Rude.","Wel.|Incompleto."], "Conceder + contrariar.", ["v-dat-wel"]),
    FB("Ik spreek geen Duits, maar ___ Engels.", ["wel"], "Contraste.", ["v-wel-part"], choices=["wel","toch","even"], tr="Não falo alemão, mas falo inglês."),
    WO("Bem, não!", ["Nou,","nee!"], "Reação.", ["v-nou"]),
  ], diff=4, mins=6)

L(5, "Partículas combinadas", "Kom maar even! Zeg het toch gewoon!",
  ["Reconhecer combinações de partículas e o seu tom"],
  vocab=[V("v-gewoon-part","gewoon (partícula)","simplesmente","adverb"), V("v-hoor","hoor","(reforço tranquilizador)","expression",note="Het is goed, hoor!"),
         V("v-zeker-part","zeker (partícula)","de certeza|com certeza","adverb"), V("v-nog-even","nog even","só mais um bocadinho","expression")],
  ex=[("Kom maar even hier.","Vem cá um bocadinho."),("Zeg het toch gewoon!","Diz lá simplesmente!"),("Het is goed, hoor!","Está tudo bem, a sério!"),("Wacht nog even.","Espera só mais um bocadinho.")],
  gram=[G("g-partikels-combinatie","Combinar partículas","As partículas combinam-se numa ordem relativamente fixa: **toch – maar – eens – even**. *Kom **maar even**.* *Probeer het **toch eens**.* **hoor** no fim da frase tranquiliza: *Geen probleem, hoor!* **gewoon** = simplesmente.",
    [("Doe maar gewoon.","Faz simplesmente / sê natural."),("Probeer het toch eens!","Experimenta lá, vá!")],
    "Não há tradução palavra a palavra: o que importa é o tom.")],
  review=["v-even-part","v-maar-part","v-toch-part","v-eens-part","v-wel-part"],
  cefr=C, exs=[
    MA([("gewoon","simplesmente"),("hoor","(tranquiliza)"),("zeker","de certeza"),("nog even","só mais um bocadinho")], "Mais partículas.", ["v-gewoon-part","v-hoor","v-zeker-part","v-nog-even"]),
    MC("«Doe maar gewoon, dan doe je al gek genoeg» é um ditado que valoriza…", ["*ser normal e não se destacar","ser extravagante|Ao contrário.","trabalhar muito|Não."], "Cultura neerlandesa.", ["v-gewoon-part"]),
    TR("pt-nl","Está tudo bem, a sério!", ["Het is goed(,) hoor","Het is goed hoor","Geen probleem(,) hoor"], "hoor.", ["v-hoor"]),
    TR("pt-nl","Espera só mais um bocadinho.", ["Wacht nog even","Wacht nog eventjes"], "nog even.", ["v-nog-even"]),
    TR("nl-pt","Zeg het toch gewoon!", ["Diz lá simplesmente","Diz simplesmente","Diz lá de uma vez"], "toch gewoon.", ["v-gewoon-part"]),
    WO("Vem cá um bocadinho.", ["Kom","maar","even","hier"], "maar antes de even.", ["v-maar-part","v-even-part"]),
    WO("Experimenta lá, vá!", ["Probeer","het","toch","eens!"], "toch antes de eens.", ["v-toch-part","v-eens-part"]),
    MC("Qual soa mais simpático ao pedir para alguém se sentar?", ["*Ga maar even zitten.","Ga zitten.|Imperativo seco.","Zitten!|Ordem."], "Partículas suavizam.", ["v-maar-part"]),
    LI("Je komt toch zeker ook?", ["Je komt toch zeker ook","Jij komt toch zeker ook"], "Tu vens também, claro, não vens?", "toch zeker.", ["v-zeker-part"]),
    FB("Geen zorgen, het komt goed, ___!", ["hoor"], "Tranquilizar.", ["v-hoor"], choices=["hoor","toch","eens"], tr="Não te preocupes, vai correr bem, a sério!"),
  ], diff=4, mins=6)

W()
